ENUMS = {'id.revision': {1: 'vice_a', 2: 'vice_b', 3: 'vice_c'}, 'msp_cause.code': {0: 'adel', 1: 'ades', 2: 'bp', 3: 'wp', 4: 'suri', 5: 'vuri', 6: 'con', 7: 'adei'}, 'DMA_DESC_CTL.direction': {0: 'write', 1: 'read'}, 'DMA_DESC_CTL.fill_source': {0: 'system', 1: 'data_register'}, 'DMA_DESC_CTL.yc': {0: 'block', 1: 'split_420', 2: 'split_422', 3: 'y_only'}, 'DMA_DESC_CTL.interleave': {0: 'block', 1: 'interleave'}, 'DMA_DESC_CTL.location': {0: 'ram_a', 1: 'ram_b', 2: 'ram_c', 3: 'msp_i_ram', 4: 'bsp_i_ram', 5: 'bsp_table', 6: 'bsp_fifo', 7: 'tlb_ram'}}
FIELD_ENUM = {'id.revision': 'id.revision', 'msp_cause.code': 'msp_cause.code', 'DMA_DESC_CTL.direction': 'DMA_DESC_CTL.direction', 'DMA_DESC_CTL.fill_source': 'DMA_DESC_CTL.fill_source', 'DMA_DESC_CTL.yc': 'DMA_DESC_CTL.yc', 'DMA_DESC_CTL.interleave': 'DMA_DESC_CTL.interleave', 'DMA_DESC_CTL.location': 'DMA_DESC_CTL.location'}
CONSTANTS = {}
TESTS = []


def decode(name, value):
    """Field name -> value for a register or word."""
    return {f: (value >> lo) & ((1 << (hi - lo + 1)) - 1) for f, (hi, lo) in FIELDS[name].items()}


def encode(name, **fields):
    v = 0
    for f, x in fields.items():
        hi, lo = FIELDS[name][f]
        if x >> (hi - lo + 1):
            raise ValueError('%s.%s: %d does not fit' % (name, f, x))
        v |= x << lo
    return v


def describe(name, value):
    """decode, with enum labels where the field has an enum."""
    out = {}
    for f, x in decode(name, value).items():
        e = ENUMS.get(FIELD_ENUM.get('%s.%s' % (name, f)))
        out[f] = e.get(x, x) if e else x
    return out


def selftest():
    for name, value, expect in TESTS:
        got = decode(name, value)
        for f, want in expect.items():
            assert got[f] == want, (name, hex(value), f, got[f], want)
    return len(TESTS)


if __name__ == '__main__':
    print('%s: %d vectors ok' % (UNIT, selftest()))
